import torch, triton, triton.language as tl, time

@triton.jit
def softmax_persistent(x, y, D, ROWS, NPROG,
                       BLOCK: tl.constexpr):
    """Persistent kernel: grid of NPROG CTAs, each processes rows round-robin.
    Limit concurrency so row being processed stays in L2 between pass1 and pass2."""
    LOG2E: tl.constexpr = 1.4426950408889634
    pid = tl.program_id(0)
    # round-robin row assignment
    for r in range(pid, ROWS, NPROG):
        base = r * D
        m = tl.full([BLOCK], float('-inf'), tl.float32)
        s = tl.zeros([BLOCK], tl.float32)
        for i in range(0, D, BLOCK):
            offs = base + i + tl.arange(0, BLOCK)
            v = tl.load(x + offs)
            m_new = tl.maximum(m, v)
            s = s * tl.exp2((m - m_new) * LOG2E) + tl.exp2((v - m_new) * LOG2E)
            m = m_new
        m_red = tl.max(m, axis=0)
        s_red = tl.sum(s, axis=0)
        inv = 1.0 / s_red
        for i in range(0, D, BLOCK):
            offs = base + i + tl.arange(0, BLOCK)
            v = tl.load(x + offs)
            tl.store(y + offs, tl.exp2((v - m_red) * LOG2E) * inv)

